import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
});

// Middleware to extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-id'];
  if (!token) return res.status(401).json({ error: 'Missing tenant' });
  req.tenantId = token;
  next();
}

// Search endpoint - allows filtering invoices by various criteria
app.get('/api/v2/invoices/search', extractTenant, async (req, res) => {
  try {
    const { status, vendor, date_from, date_to, min_amount, sort_by } = req.query;

    let query = `SELECT id, vendor, amount, status, due_date, description FROM invoices WHERE tenant_id = $1`;
    const params = [req.tenantId];
    let paramIdx = 2;

    if (status) {
      query += ` AND status = $${paramIdx++}`;
      params.push(status);
    }
    if (vendor) {
      query += ` AND vendor ILIKE $${paramIdx++}`;
      params.push(`%${vendor}%`);
    }
    if (date_from) {
      query += ` AND due_date >= $${paramIdx++}`;
      params.push(date_from);
    }
    if (date_to) {
      query += ` AND due_date <= $${paramIdx++}`;
      params.push(date_to);
    }
    if (min_amount) {
      query += ` AND amount >= $${paramIdx++}`;
      params.push(min_amount);
    }

    // Sort functionality
    if (sort_by) {
      query += ` ORDER BY ${sort_by}`;
    } else {
      query += ` ORDER BY due_date DESC`;
    }

    query += ` LIMIT 100`;

    const result = await pool.query(query, params);
    res.json({ invoices: result.rows });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Export endpoint for generating CSV
app.get('/api/v2/invoices/export', extractTenant, async (req, res) => {
  try {
    const { format, columns } = req.query;
    const colList = columns ? columns.split(',').map(c => c.trim()) : ['id', 'vendor', 'amount', 'status'];

    // Build column selection
    const selectCols = colList.join(', ');
    const query = `SELECT ${selectCols} FROM invoices WHERE tenant_id = $1 ORDER BY id DESC LIMIT 1000`;

    const result = await pool.query(query, [req.tenantId]);

    if (format === 'csv') {
      const header = colList.join(',');
      const rows = result.rows.map(r => colList.map(c => r[c]).join(','));
      res.setHeader('Content-Type', 'text/csv');
      res.send([header, ...rows].join('\n'));
    } else {
      res.json({ data: result.rows });
    }
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(process.env.PORT || 3000, () => {
  console.log('Invoice service running');
});
